// Fox Pet — a pixel-art fox that lives on the desktop.
// Sprites are generated by tools/gen_fox.py (44x30 px, scaled x3).

import GLib from 'gi://GLib';
import Gio from 'gi://Gio';
import St from 'gi://St';
import Clutter from 'gi://Clutter';
import Meta from 'gi://Meta';

import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import * as PanelMenu from 'resource:///org/gnome/shell/ui/panelMenu.js';
import * as PopupMenu from 'resource:///org/gnome/shell/ui/popupMenu.js';
import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';

const SPRITE_W = 132;
const SPRITE_H = 90;
const TICK_MS = 50;

// name -> number of frames
const ANIMS = {walk: 6, run: 6, stand: 5, sit: 6, groom: 4, sleep: 4, jump: 2};

const DEFAULTS = {visible: true, follow: false, aboveWindows: true};

const rand = (a, b) => a + Math.random() * (b - a);
const randi = (a, b) => Math.floor(rand(a, b + 1));
const chance = p => Math.random() < p;

function pickWeighted(table) {
    const total = table.reduce((s, [, w]) => s + w, 0);
    let r = Math.random() * total;
    for (const [v, w] of table) {
        r -= w;
        if (r <= 0)
            return v;
    }
    return table[table.length - 1][0];
}

class Fox {
    constructor(dir) {
        this._sf = St.ThemeContext.get_for_stage(global.stage).scale_factor;
        this.w = SPRITE_W * this._sf;
        this.h = SPRITE_H * this._sf;
        this.G = 1.6 * this._sf;

        // Fixed layout: frames at (0,0), plus a reactive hitbox for dragging.
        this.actor = new St.Widget({
            reactive: false,
            width: this.w,
            height: this.h,
        });

        // One pre-built child per frame; we only toggle visibility.
        this._frames = {};
        for (const [name, n] of Object.entries(ANIMS)) {
            for (let i = 0; i < n; i++) {
                for (const d of ['r', 'l']) {
                    const path = GLib.build_filenamev([dir, 'sprites', `${name}_${i}_${d}.png`]);
                    const w = new St.Widget({
                        reactive: false,
                        visible: false,
                        style: `background-image: url("${path}"); width: ${SPRITE_W}px; height: ${SPRITE_H}px;`,
                    });
                    this.actor.add_child(w);
                    this._frames[`${name}_${i}_${d}`] = w;
                }
            }
        }

        this._hit = new St.Widget({
            reactive: true,
            track_hover: true,
            x: Math.round(this.w * 0.2),
            y: Math.round(this.h * 0.3),
            width: Math.round(this.w * 0.6),
            height: Math.round(this.h * 0.7),
        });
        this.actor.add_child(this._hit);
        this._hit.connect('button-press-event', (_a, e) => this._onPress(e));
        this._hit.connect('motion-event', (_a, e) => this._onMotion(e));
        this._hit.connect('button-release-event', (_a, e) => this._onRelease(e));

        this._shown = null;
        this.dead = false;
        this.actor.connect('destroy', () => {
            this.dead = true;
            this._endGrab();
        });

        const prim = Main.layoutManager.primaryMonitor;
        this.x = prim.x + prim.width / 2;
        this.dir = 'r';
        this.vx = 0;
        this.vy = 0;
        this.airborne = false;
        this.dragging = false;
        this.follow = false;
        this._hopCooldown = 0;
        this._leapCooldown = 0;
        this._followPause = 0;
        this.platWin = null;
        this.platRect = null;
        this.plat = null;
        this._plats = this._platforms();
        this.y = this._floorAt(this.x).y;

        this._setState('sit', 60);
    }

    // ---------------------------------------------------------- geometry

    _bounds() {
        const ms = Main.layoutManager.monitors;
        const minX = Math.min(...ms.map(m => m.x));
        const maxX = Math.max(...ms.map(m => m.x + m.width));
        return [minX + this.w / 2, maxX - this.w / 2];
    }

    _monitorAt(x) {
        const ms = Main.layoutManager.monitors;
        const i = ms.findIndex(m => x >= m.x && x < m.x + m.width);
        return i >= 0 ? i : Main.layoutManager.primaryIndex;
    }

    monitorIndex() {
        return this._monitorAt(this.x);
    }

    _floorAt(x) {
        const mon = this._monitorAt(x);
        return this._plats.find(p => !p.win && p.mon === mon) ?? this._plats[0];
    }

    // Surfaces the fox can stand on: the bottom of every work area plus the
    // visible parts of the top edges of normal windows on this workspace.
    _platforms() {
        const lm = Main.layoutManager;
        const plats = [];
        lm.monitors.forEach((m, i) => {
            const wa = lm.getWorkAreaForMonitor(i);
            plats.push({win: null, mon: i, y: wa.y + wa.height, x0: wa.x, x1: wa.x + wa.width});
        });

        const ws = global.workspace_manager.get_active_workspace();
        const types = [Meta.WindowType.NORMAL, Meta.WindowType.DIALOG,
            Meta.WindowType.MODAL_DIALOG, Meta.WindowType.UTILITY];
        let wins = global.get_window_actors()
            .map(a => a.meta_window)
            .filter(w => w && !w.minimized && w.showing_on_its_workspace() &&
                (w.is_on_all_workspaces() || w.get_workspace() === ws) &&
                types.includes(w.get_window_type()) && !w.is_fullscreen());
        wins = global.display.sort_windows_by_stacking(wins);
        const rects = wins.map(w => w.get_frame_rect());
        const [bx0, bx1] = this._bounds().map((v, k) => v + (k ? 1 : -1) * this.w / 2);
        const minW = this.w * 0.5;

        for (let i = 0; i < wins.length; i++) {
            const r = rects[i];
            const y = r.y;
            const mon = wins[i].get_monitor();
            if (mon < 0 || mon >= lm.monitors.length)
                continue;
            const wa = lm.getWorkAreaForMonitor(mon);
            // Skip maximized / glued-to-the-top windows: the fox would hide under the panel.
            if (y < wa.y + 12 * this._sf || y >= wa.y + wa.height - 4)
                continue;
            let segs = [[Math.max(r.x, bx0), Math.min(r.x + r.width, bx1)]];
            for (let j = i + 1; j < wins.length; j++) {
                const q = rects[j];
                if (!(q.y < y && q.y + q.height > y - 2))
                    continue;
                const next = [];
                for (const [a, b] of segs) {
                    if (q.x >= b || q.x + q.width <= a) {
                        next.push([a, b]);
                        continue;
                    }
                    if (q.x > a)
                        next.push([a, q.x]);
                    if (q.x + q.width < b)
                        next.push([q.x + q.width, b]);
                }
                segs = next;
            }
            for (const [a, b] of segs) {
                if (b - a >= minW)
                    plats.push({win: wins[i], mon, y, x0: a, x1: b, rect: {x: r.x, y: r.y, w: r.width, h: r.height}});
            }
        }
        return plats;
    }

    _margin(p) {
        return Math.min(this.w * 0.25, (p.x1 - p.x0) / 2);
    }

    _clampTo(p, x) {
        const m = this._margin(p);
        return Math.max(p.x0 + m, Math.min(p.x1 - m, x));
    }

    _samePlat(a, b) {
        return a && b && a.win === b.win && a.x0 === b.x0 && a.y === b.y;
    }

    // Nearest surface at or below the point (x, y).
    _platBelow(x, y) {
        let best = null;
        for (const p of this._plats) {
            if (x >= p.x0 && x <= p.x1 && p.y >= y - 4 && (!best || p.y < best.y))
                best = p;
        }
        return best ?? this._floorAt(x);
    }

    // Keep standing on the current surface; ride along if its window moves.
    _ride() {
        if (!this.platWin) {
            const f = this._floorAt(this.x);
            this.plat = f;
            this.y = f.y;
            return;
        }
        const mine = this._plats.filter(p => p.win === this.platWin);
        if (mine.length === 0) {
            this._startFall();
            return;
        }
        const r = mine[0].rect;
        if (this.platRect && r.w === this.platRect.w &&
            (r.x !== this.platRect.x || r.y !== this.platRect.y)) {
            const dx = r.x - this.platRect.x;
            this.x += dx;
            if (this.target !== null)
                this.target += dx;
        }
        this.platRect = r;
        const p = mine.find(s => this.x >= s.x0 - 2 && this.x <= s.x1 + 2);
        if (!p) {
            this._startFall();
            return;
        }
        this.plat = p;
        this.y = p.y;
    }

    _startFall(vx = 0, vy = 0) {
        this.airborne = true;
        this.vx = vx;
        this.vy = vy;
        this.platWin = null;
        this.platRect = null;
        this.plat = null;
        if (!['leap', 'fall'].includes(this.state))
            this._setState('fall', 0);
    }

    _land(p) {
        const wasState = this.state;
        this.airborne = false;
        this.vx = this.vy = 0;
        this.y = p.y;
        this.x = this._clampTo(p, this.x);
        this.plat = p;
        this.platWin = p.win;
        this.platRect = p.rect ?? null;
        if (wasState === 'fall' && this._followPause > 0)
            this._setState('sit', randi(400, 700)); // put here by the user: stay a while
        else if (wasState === 'fall')
            this._setState('stand', randi(15, 30));
        else if (wasState === 'leap')
            this._setState('stand', randi(8, 25));
        else if (wasState === 'sleep')
            this._setState('stand', 30);
    }

    // ---------------------------------------------------------- dragging

    _onPress(e) {
        if (e.get_button() !== 1)
            return Clutter.EVENT_PROPAGATE;
        const [ex, ey] = e.get_coords();
        this._drag = {sx: ex, sy: ey, offX: ex - this.x, offY: ey - this.y, moved: false,
            hist: [[ex, ey, GLib.get_monotonic_time()]]};
        this._grab = global.stage.grab(this._hit);
        return Clutter.EVENT_STOP;
    }

    _onMotion(e) {
        if (!this._drag)
            return Clutter.EVENT_PROPAGATE;
        const [ex, ey] = e.get_coords();
        const d = this._drag;
        if (!d.moved && Math.hypot(ex - d.sx, ey - d.sy) > 6 * this._sf) {
            d.moved = true;
            this.dragging = true;
            this.airborne = false;
            this.platWin = null;
            this.plat = null;
            this._setState('drag', 0);
        }
        if (d.moved) {
            this.x = ex - d.offX;
            this.y = ey - d.offY;
            const last = d.hist[d.hist.length - 1];
            if (Math.abs(ex - last[0]) > 2 * this._sf)
                this.dir = ex > last[0] ? 'r' : 'l';
            d.hist.push([ex, ey, GLib.get_monotonic_time()]);
            if (d.hist.length > 8)
                d.hist.shift();
            this._render();
        }
        return Clutter.EVENT_STOP;
    }

    _onRelease(e) {
        if (!this._drag)
            return Clutter.EVENT_PROPAGATE;
        const d = this._drag;
        this._drag = null;
        this._endGrab();
        if (!d.moved) {
            // simple click: hop (and wake up)
            this.jump();
            return Clutter.EVENT_STOP;
        }
        this.dragging = false;
        // throw velocity from the last ~100 ms of pointer motion
        const now = GLib.get_monotonic_time();
        const recent = d.hist.filter(h => now - h[2] < 120000);
        let vx = 0, vy = 0;
        if (recent.length >= 2) {
            const a = recent[0], b = recent[recent.length - 1];
            const dt = Math.max(1, (b[2] - a[2]) / 1000) / TICK_MS;
            const lim = 30 * this._sf;
            vx = Math.max(-lim, Math.min(lim, (b[0] - a[0]) / dt));
            vy = Math.max(-lim, Math.min(lim, (b[1] - a[1]) / dt));
        }
        if (Math.abs(vx) > 1.5 * this._sf)
            this.dir = vx > 0 ? 'r' : 'l';
        const [lo, hi] = this._bounds();
        this.x = Math.max(lo, Math.min(hi, this.x));
        this._followPause = 600; // stay where it was put for ~30 s
        this._setState('fall', 0);
        this._startFall(vx, vy);
        return Clutter.EVENT_STOP;
    }

    _endGrab() {
        this._grab?.dismiss();
        this._grab = null;
    }

    // ---------------------------------------------------------- states

    _setState(state, ticks, opts = {}) {
        this.state = state;
        this.ticks = ticks;
        this.age = 0;
        this.target = opts.target ?? null;
        this.frame = 0;
    }

    _goTo(x, run) {
        const p = this.plat ?? this._floorAt(this.x);
        x = this._clampTo(p, x);
        if (Math.abs(x - this.x) < 8 * this._sf) {
            this._setState('sit', randi(80, 200));
            return;
        }
        this._setState(run ? 'run' : 'walk', 100000, {target: x});
    }

    // Crouch for a moment, then leap onto surface p at x.
    _leapTo(p, x) {
        x = this._clampTo(p, x);
        this.dir = x >= this.x ? 'r' : 'l';
        this._leapPlan = {p, x};
        this._setState('prep', 5);
    }

    _doLeap() {
        const {p, x} = this._leapPlan;
        this._leapPlan = null;
        const G = this.G;
        const dx = x - this.x;
        const dy = p.y - this.y;
        let T = Math.max(12, Math.min(40, Math.round(Math.abs(dx) / (22 * this._sf))));
        // make sure we are already descending when we reach the target height
        while (dy + G * T * (T - 1) / 2 < G * T * T * 0.12)
            T++;
        const vx = dx / T;
        const vy = (dy - G * T * (T - 1) / 2) / T;
        this._setState('leap', 0);
        this._startFall(vx, vy);
        this.dir = vx >= 0 ? 'r' : 'l';
    }

    _leapRandom() {
        const cands = this._plats.filter(p => !this._samePlat(p, this.plat));
        if (cands.length === 0)
            return false;
        const p = pickWeighted(cands.map(c => [c, c.win ? 3 : 1]));
        const m = this._margin(p);
        this._leapTo(p, rand(p.x0 + m, p.x1 - m));
        return true;
    }

    _chooseNext() {
        const p = this.plat ?? this._floorAt(this.x);
        const m = this._margin(p);
        const narrow = p.x1 - p.x0 < this.w * 1.2;
        const prev = this.state;
        let next;
        if (prev === 'sit')
            next = pickWeighted([['groom', 20], ['sleep', 12], ['stand', 20], ['walk', 25], ['run', 8], ['leap', 25]]);
        else if (prev === 'sleep')
            next = 'stand';
        else if (prev === 'groom')
            next = pickWeighted([['sit', 50], ['sleep', 20], ['walk', 15], ['leap', 15]]);
        else
            next = pickWeighted([['walk', 25], ['run', 10], ['leap', 25], ['sit', 28], ['stand', 7], ['cursor', 5]]);
        if (narrow && (next === 'walk' || next === 'run'))
            next = 'leap';

        switch (next) {
        case 'walk':
            this._goTo(rand(p.x0 + m, p.x1 - m), false);
            break;
        case 'run':
            this._goTo(rand(p.x0 + m, p.x1 - m), true);
            break;
        case 'leap':
            if (!this._leapRandom())
                this._setState('sit', randi(80, 300));
            break;
        case 'cursor':
            this.call();
            break;
        case 'sit':
            this._setState('sit', randi(80, 300));
            break;
        case 'stand':
            this._setState('stand', randi(30, 80));
            break;
        case 'groom':
            this._setState('groom', randi(50, 100));
            break;
        case 'sleep':
            this._setState('sleep', randi(600, 2000));
            break;
        }
    }

    jump() {
        if (this.airborne || this.dragging)
            return;
        const st = this.state === 'sleep' ? 'stand' : this.state;
        this._setState(st === 'prep' ? 'stand' : st, 40, {target: this.target});
        this.airborne = true;
        this.vx = 0;
        this.vy = -11.5 * this._sf;
    }

    call() {
        if (this.dragging)
            return;
        const [px, py] = global.get_pointer();
        if (this.airborne)
            return;
        const tp = this._platBelow(px, py);
        if (!this._samePlat(tp, this.plat))
            this._leapTo(tp, px);
        else
            this._goTo(px, Math.abs(px - this.x) > 400 * this._sf);
    }

    sleep() {
        if (!this.airborne && !this.dragging)
            this._setState('sleep', randi(1200, 3000));
    }

    // ---------------------------------------------------------- tick

    tick() {
        this.age++;
        if (this.dragging) {
            this._render();
            return;
        }
        if (this._hopCooldown > 0)
            this._hopCooldown--;
        if (this._leapCooldown > 0)
            this._leapCooldown--;
        if (this._followPause > 0 && !this.airborne)
            this._followPause--;

        this._plats = this._platforms();
        if (!this.airborne)
            this._ride();

        const [px, py] = global.get_pointer();

        // Hovering over a sleeping fox wakes it up.
        if (this.state === 'sleep' && this._hit.hover && !this.airborne && this._hopCooldown === 0) {
            this._hopCooldown = 60;
            this.jump();
        }

        // Follow-cursor mode.
        if (this.follow && this._followPause === 0 && !this.airborne && !['sleep', 'prep'].includes(this.state)) {
            const tp = this._platBelow(px, py);
            if (!this._samePlat(tp, this.plat)) {
                if (this._leapCooldown === 0) {
                    this._leapCooldown = 30;
                    this._leapTo(tp, px);
                }
            } else {
                const dist = px - this.x;
                const far = 140 * this._sf;
                if (Math.abs(dist) > far) {
                    const run = Math.abs(dist) > 450 * this._sf;
                    if (!['walk', 'run'].includes(this.state) || Math.abs(this.target - px) > far ||
                        (run && this.state === 'walk'))
                        this._goTo(px - Math.sign(dist) * far * 0.5, run);
                } else if (this.state === 'walk' || this.state === 'run') {
                    this.dir = dist >= 0 ? 'r' : 'l';
                    this._setState('sit', randi(60, 200));
                }
            }
        }

        // Movement along the current surface.
        if (!this.airborne && (this.state === 'walk' || this.state === 'run')) {
            const speed = (this.state === 'run' ? 6 : 1.6) * this._sf;
            if (this.plat)
                this.target = this._clampTo(this.plat, this.target);
            const d = this.target - this.x;
            this.dir = d >= 0 ? 'r' : 'l';
            if (Math.abs(d) <= speed) {
                this.x = this.target;
                if (this.follow) {
                    this.dir = px >= this.x ? 'r' : 'l';
                    this._setState('sit', randi(60, 200));
                } else {
                    this._chooseNext();
                }
            } else {
                this.x += Math.sign(d) * speed;
                if (this.state === 'run' && chance(0.012))
                    this.jump();
            }
        } else if (!this.airborne) {
            this.ticks--;
            if (this.ticks <= 0) {
                if (this.state === 'prep' && this._leapPlan)
                    this._doLeap();
                else
                    this._chooseNext();
            }
        }

        // Ballistics: hops, leaps, falls and throws.
        if (this.airborne) {
            const prevY = this.y;
            this.x += this.vx;
            this.y += this.vy;
            this.vy += this.G;
            const [lo, hi] = this._bounds();
            if (this.x < lo || this.x > hi) {
                this.x = Math.max(lo, Math.min(hi, this.x));
                this.vx = -this.vx * 0.3;
                if (Math.abs(this.vx) > 0.5)
                    this.dir = this.vx > 0 ? 'r' : 'l';
            }
            if (this.vy > 0) {
                let best = null;
                for (const p of this._plats) {
                    if (this.x < p.x0 || this.x > p.x1)
                        continue;
                    // the floor always catches; window tops only from above
                    const crossed = this.y >= p.y && (!p.win ? true : prevY <= p.y + 1);
                    if (crossed && (!best || p.y < best.y))
                        best = p;
                }
                if (best)
                    this._land(best);
            }
        }

        this._render();
    }

    _frameName() {
        const a = this.age;
        if (this.dragging)
            return 'jump_1';
        if (this.airborne)
            return `jump_${this.vy < 0 ? 0 : 1}`;
        switch (this.state) {
        case 'walk':
            return `walk_${Math.floor(a / 3) % 6}`;
        case 'run':
            return `run_${Math.floor(a / 2) % 6}`;
        case 'prep':
            return 'stand_0';
        case 'stand': {
            const f = Math.floor(a / 6) % 8;
            return `stand_${f < 4 ? f : (f === 6 ? 4 : 0)}`;
        }
        case 'sit': {
            const cyc = a % 120;
            if (cyc >= 100 && cyc < 103)
                return 'sit_4'; // blink
            if (cyc >= 60 && cyc < 64 && (Math.floor(a / 120) % 3 === 1))
                return 'sit_5'; // ear flick
            return `sit_${Math.floor(a / 8) % 4}`;
        }
        case 'groom':
            return `groom_${[0, 1, 2, 1][Math.floor(a / 4) % 4]}`;
        case 'sleep':
            return `sleep_${Math.floor(a / 14) % 4}`;
        }
        return 'sit_0';
    }

    _render() {
        const key = `${this._frameName()}_${this.dir}`;
        if (key !== this._shown) {
            if (this._shown)
                this._frames[this._shown].hide();
            this._frames[key].show();
            this._shown = key;
        }
        this.actor.set_position(Math.round(this.x - this.w / 2), Math.round(this.y - this.h));
    }

    destroy() {
        this._endGrab();
        if (!this.dead)
            this.actor.destroy();
    }
}

export default class FoxPetExtension extends Extension {
    enable() {
        this._settingsPath = GLib.build_filenamev([GLib.get_user_config_dir(), 'fox-pet.json']);
        this._settings = {...DEFAULTS, ...this._loadSettings()};

        this._fox = new Fox(this.path);
        this._fox.follow = this._settings.follow;
        this._placeActor();

        this._buildIndicator();

        this._overviewIds = [
            Main.overview.connect('showing', () => this._updateVisibility()),
            Main.overview.connect('hidden', () => this._updateVisibility()),
        ];
        this._fsId = global.display.connect('in-fullscreen-changed', () => this._updateVisibility());
        this._monId = Main.layoutManager.connect('monitors-changed', () => this._updateVisibility());

        this._timer = GLib.timeout_add(GLib.PRIORITY_DEFAULT, TICK_MS, () => {
            if (this._fox.dead)
                return GLib.SOURCE_REMOVE;
            if (this._fox.actor.visible)
                this._fox.tick();
            return GLib.SOURCE_CONTINUE;
        });
        this._updateVisibility();
    }

    disable() {
        if (this._timer) {
            GLib.source_remove(this._timer);
            this._timer = 0;
        }
        this._overviewIds?.forEach(id => Main.overview.disconnect(id));
        this._overviewIds = null;
        if (this._fsId)
            global.display.disconnect(this._fsId);
        if (this._monId)
            Main.layoutManager.disconnect(this._monId);
        this._fsId = this._monId = 0;
        this._indicator?.destroy();
        this._indicator = null;
        this._fox?.destroy();
        this._fox = null;
    }

    // ---------------------------------------------------------- helpers

    _loadSettings() {
        try {
            const [ok, bytes] = GLib.file_get_contents(this._settingsPath);
            if (ok)
                return JSON.parse(new TextDecoder().decode(bytes));
        } catch (e) {}
        return {};
    }

    _saveSettings() {
        try {
            GLib.file_set_contents(this._settingsPath, JSON.stringify(this._settings, null, 2));
        } catch (e) {
            console.warn(`fox-pet: cannot save settings: ${e.message}`);
        }
    }

    _placeActor() {
        const actor = this._fox.actor;
        actor.get_parent()?.remove_child(actor);
        if (this._settings.aboveWindows) {
            // Above windows, below the top panel / popups.
            Main.layoutManager.uiGroup.insert_child_below(actor, Main.layoutManager.panelBox);
        } else {
            // On the desktop: right above the wallpaper, below all windows.
            global.window_group.insert_child_above(actor, Main.layoutManager._backgroundGroup);
        }
    }

    _updateVisibility() {
        if (!this._fox)
            return;
        const mon = Main.layoutManager.monitors[this._fox.monitorIndex()];
        const fullscreen = this._settings.aboveWindows && mon?.inFullscreen;
        this._fox.actor.visible = this._settings.visible && !Main.overview.visible && !fullscreen;
    }

    _buildIndicator() {
        this._indicator = new PanelMenu.Button(0.0, 'Fox Pet', false);
        this._indicator.add_child(new St.Icon({
            gicon: Gio.FileIcon.new(Gio.File.new_for_path(GLib.build_filenamev([this.path, 'icon.png']))),
            style_class: 'system-status-icon',
        }));
        const menu = this._indicator.menu;

        const show = new PopupMenu.PopupSwitchMenuItem('Показывать лису', this._settings.visible);
        show.connect('toggled', (_i, v) => {
            this._settings.visible = v;
            this._saveSettings();
            this._updateVisibility();
        });
        menu.addMenuItem(show);

        const follow = new PopupMenu.PopupSwitchMenuItem('Ходить за курсором', this._settings.follow);
        follow.connect('toggled', (_i, v) => {
            this._settings.follow = v;
            this._fox.follow = v;
            this._saveSettings();
        });
        menu.addMenuItem(follow);

        const above = new PopupMenu.PopupSwitchMenuItem('Поверх окон', this._settings.aboveWindows);
        above.connect('toggled', (_i, v) => {
            this._settings.aboveWindows = v;
            this._saveSettings();
            this._placeActor();
            this._updateVisibility();
        });
        menu.addMenuItem(above);

        menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());

        menu.addAction('Позвать к курсору', () => {
            // Pointer is on the panel when the menu is used: run toward its x.
            this._fox.call();
        });
        menu.addAction('Подпрыгнуть', () => this._fox.jump());
        menu.addAction('Уложить спать', () => this._fox.sleep());

        Main.panel.addToStatusArea(this.uuid, this._indicator);
    }
}
